from functools import wraps
def announce(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        print("Starting")
        return fn(*args, **kwargs)
    return wrapper
@announce
def greet(name):
    print("Hello", name)
greet("Anu")

