class Result:
    def __init__(self, score):
        self.score = score
    @property
    def score(self):
        return self._score
    @score.setter
    def score(self, value):
        if not 0 <= value <= 100:
            raise ValueError("invalid")
        self._score = value
print(Result(89).score)

